/* Token Radar — dark radar-room theme. Palette: ink navy, teal radar,
   amber for the top of the board. Two radii, two families, one spacing scale. */
:root {
  --canvas: #0b1210;
  --surface: #111c18;
  --surface-2: #16241f;
  --ink: #e8f0ec;
  --muted: #9db3a9;
  --border: #26382f;
  --accent: #2dd4a7;
  --amber: #f2b544;
  --negative: #ff7a6b;
  --radius-control: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --s1: 4px; --s2: 8px; --s3: 12px; --s4: 16px; --s5: 24px; --s6: 32px; --s7: 48px;
}
* { box-sizing: border-box; }
