.field label { color: var(--muted); font-size: 12px; }
.field input, .field select { min-height: 36px; padding: 0 var(--s3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-2); min-width: 150px; color: var(--ink); }
.field input { min-width: 260px; }
